INSERT INTO contenido (coleccion, slug, titulo, orden, data) VALUES ('productos_en', 'w1770-triflex', 'W1770 Triflex', 1, '{"slug":"w1770-triflex","title":"W1770 Triflex","seo_title":"W1770 Triflex · Super Walter — Award-winning seeder at CITA 2025","seo_description":"W1770 Triflex: Super Walter seeder with a triple-articulated frame, Air Drill metering and ISOBUS monitoring. CITA 2025 Innovation Award.","og_title":"W1770 Triflex · Super Walter","og_description":"Triflex frame, Air Drill and ISOBUS. The seeder that won the CITA 2025 Award.","hero_image_alt":"Super Walter W1770 seeder at work at sunset in a stubble field","hero_pills":[{"text":"★ CITA 2025 Award","variant":"amarillo"},{"text":"Fine grain · High capacity","variant":"outline"}],"lead":"Triple-articulated folding frame and Air Drill discs. The answer when every day of seeding counts.","cta_hero_text":"Ask about the W1770","ficha_eyebrow":"Technology and innovation","ficha_heading":"The seeder designed so every seed finds its place, on any terrain.","ficha_image_alt":"Tractor with a Super Walter seeder working a hillside at sunset","ficha_badge":"Triflex frame","features":[{"icon":"bars","title":"Section control","text":"The machine automatically shuts off rows that have already been seeded, avoiding overlap and lowering the cost per hectare."},{"icon":"clock","title":"Air Drill metering","text":"Precise, steady pneumatic distribution of seed and fertilizer, even at high travel speeds."},{"icon":"monitor","title":"ISOBUS monitoring","text":"Full control from the cab: density, inputs and the performance of each unit in real time."},{"icon":"cube","title":"Triflex frame","text":"Triple articulation that follows the terrain and keeps seeding depth even across the full working width."}],"benefits_heading":"An innovation award you can feel in the field.","benefits":[{"number":"01","title":"Proven robustness","text":"Built to last season after season, with spare parts available across the country."},{"number":"02","title":"Real precision","text":"Seeding uniformity that translates into better emergence and higher yield per hectare."},{"number":"03","title":"Input efficiency","text":"Section control and precise metering: every seed and every kilo of fertilizer exactly where it belongs."},{"number":"04","title":"Close to you","text":"Argentine-made, with direct support and a dealer network that knows your area."}],"cta_title_html":"Want a quote on the <em>W1770 Triflex</em>?","cta_lead":"Fill out the form and a Super Walter advisor will get in touch to move forward with your quote.","form_message_placeholder":"Hectares, crop, payment method...","listing_badge":{"text":"★ CITA 2025 Award"},"homepage_chips":["Triflex frame","Air Drill","ISOBUS"],"homepage_link_text":"View the W1770 overview"}') ON DUPLICATE KEY UPDATE titulo = VALUES(titulo), orden = VALUES(orden), data = VALUES(data);
INSERT INTO contenido (coleccion, slug, titulo, orden, data) VALUES ('productos_en', 'w660', 'W660', 2, '{"slug":"w660","title":"W660","seo_title":"W660 · Super Walter — Fine grain seeder","seo_description":"W660: Super Walter fine grain seeder delivering capacity and seeding uniformity without compromising precision. Built for demanding producers.","og_title":"W660 · Super Walter","og_description":"Capacity and seeding uniformity without compromising precision.","hero_image_alt":"Front view of the Super Walter W660 seeder over a field under a clear sky","hero_pills":[{"text":"Fine grain","variant":"outline"}],"lead":"Capacity and seeding uniformity without compromising precision, built for demanding producers.","cta_hero_text":"Ask about the W660","ficha_eyebrow":"Model overview","ficha_heading":"Fine grain, capacity and uniformity in a single machine.","ficha_image_alt":"Super Walter W660 seeder","features":[{"icon":"clock","title":"Seeding uniformity","text":"Even seed distribution across the full working width, season after season."},{"icon":"cube","title":"Rugged construction","text":"A structure built to work season after season without giving up performance."},{"icon":"bars","title":"Work capacity","text":"Built to cover more hectares per day without sacrificing seeding precision."}],"benefits_heading":"Built for demanding producers.","benefits":[{"number":"01","title":"Proven robustness","text":"Built to last season after season, with spare parts available across the country."},{"number":"02","title":"Real precision","text":"Seeding uniformity that translates into better emergence and higher yield per hectare."},{"number":"03","title":"Input efficiency","text":"Precise metering: every seed and every kilo of fertilizer exactly where it belongs."},{"number":"04","title":"Close to you","text":"Argentine-made, with direct support and a dealer network that knows your area."}],"cta_title_html":"Want a quote on the <em>W660</em>?","cta_lead":"Fill out the form and a Super Walter advisor will get in touch to move forward with your quote.","form_message_placeholder":"Hectares, crop, payment method...","listing_badge":{"text":"Fine grain"}}') ON DUPLICATE KEY UPDATE titulo = VALUES(titulo), orden = VALUES(orden), data = VALUES(data);
INSERT INTO contenido (coleccion, slug, titulo, orden, data) VALUES ('productos_en', 'w650-imperial', 'W650 Imperial', 3, '{"slug":"w650-imperial","title":"W650 Imperial","seo_title":"W650 Imperial · Super Walter — Autotrailer seeder","seo_description":"W650 Imperial: Super Walter autotrailer seeder, combining transport versatility and seeding in a single machine. Ready to move between fields in minutes.","og_title":"W650 Imperial · Super Walter","og_description":"Transport versatility and seeding in a single machine.","hero_image_alt":"Aerial view of the Super Walter W650 Imperial seeder folded over stubble","hero_pills":[{"text":"Autotrailer","variant":"outline"}],"lead":"Transport versatility and seeding in a single machine. Ready to move between fields in minutes.","cta_hero_text":"Ask about the W650 Imperial","ficha_eyebrow":"Model overview","ficha_heading":"It folds, travels and goes back to seeding, all in the same machine.","ficha_image_alt":"Aerial view of the Super Walter W650 Imperial seeder folded over stubble","ficha_badge":"Autotrailer","features":[{"icon":"cube","title":"Autotrailer system","text":"Built-in folding for travel on roads or farm tracks, with no need for a separate rig."},{"icon":"clock","title":"Speed between fields","text":"Less time maneuvering and more time seeding, especially when the weather window is short."},{"icon":"bars","title":"Seeding versatility","text":"One machine to transport and seed, designed for fields spread across different areas."},{"icon":"monitor","title":"Super Walter robustness","text":"The same build quality as the entire lineup, adapted to a machine designed to be on the move."}],"benefits_heading":"Mobility without compromising precision.","benefits":[{"number":"01","title":"Proven robustness","text":"Built to last season after season, with spare parts available across the country."},{"number":"02","title":"Real precision","text":"Seeding uniformity that translates into better emergence and higher yield per hectare."},{"number":"03","title":"Input efficiency","text":"Precise metering: every seed and every kilo of fertilizer exactly where it belongs."},{"number":"04","title":"Close to you","text":"Argentine-made, with direct support and a dealer network that knows your area."}],"cta_title_html":"Want a quote on the <em>W650 Imperial</em>?","cta_lead":"Fill out the form and a Super Walter advisor will get in touch to move forward with your quote.","form_message_placeholder":"Hectares, crop, payment method...","listing_badge":{"text":"Autotrailer"}}') ON DUPLICATE KEY UPDATE titulo = VALUES(titulo), orden = VALUES(orden), data = VALUES(data);
INSERT INTO contenido (coleccion, slug, titulo, orden, data) VALUES ('productos_en', 'familia-w630-w4500-rastra-at', 'W630 · W4500 · Rastra AT', 4, '{"slug":"familia-w630-w4500-rastra-at","title":"W630 · W4500 · Rastra AT","seo_title":"W630 · W4500 · Rastra AT · Super Walter — The complete family","seo_description":"From three-point fine grain seeding to coarse grain, plus soil preparation. W630, W4500 and Rastra AT: the Super Walter catalog that covers every need in the field.","og_title":"W630 · W4500 · Rastra AT · Super Walter","og_description":"A catalog that covers every need in the field.","hero_image_alt":"Super Walter seeder pulled by a tractor hard at work","hero_pills":[{"text":"Complete family","variant":"outline"}],"lead":"From three-point fine grain seeding to coarse grain. A catalog that covers every need in the field.","cta_hero_text":"Talk to an advisor","ficha_eyebrow":"Three machines, one catalog","ficha_heading":"A model for every stage of the work in the field.","sub_models":[{"icon":"bars","title":"W630 · Fine grain, three-point","text":"Three-point seeder designed for fine grain, ideal for smaller fields without sacrificing precision."},{"icon":"clock","title":"W4500 · Coarse grain","text":"Seeder designed for coarse grain, with Super Walter robustness in every seeding unit."},{"icon":"monitor","title":"Rastra AT","text":"Disc harrow for soil preparation before seeding, with the strength that heavy-duty work demands."}],"benefits_heading":"The same Super Walter engineering at every stage of the work.","benefits":[{"number":"01","title":"Proven robustness","text":"Machines built to last season after season, with spare parts available across the country."},{"number":"02","title":"Real precision","text":"Seeding uniformity that translates into better emergence and higher yield per hectare."},{"number":"03","title":"Complete catalog","text":"From soil preparation to fine or coarse grain seeding, all within the same brand."},{"number":"04","title":"Close to you","text":"Argentine-made, with direct support and a dealer network that knows your area."}],"cta_title_html":"Which of the three do you need?","cta_lead":"Fill out the form and a Super Walter advisor will get in touch to help you choose the right machine.","form_message_placeholder":"Tell us which model interests you and why...","listing_badge":{"text":"Complete family"}}') ON DUPLICATE KEY UPDATE titulo = VALUES(titulo), orden = VALUES(orden), data = VALUES(data);
INSERT INTO contenido (coleccion, slug, titulo, orden, data) VALUES ('novedades_en', 'certificacion-ce', 'Super Walter conquers Europe! We have earned CE certification', 1, '{"slug":"certificacion-ce","title":"Super Walter conquers Europe! We have earned CE certification","seo_title":"Super Walter conquers Europe: CE certification · News","seo_description":"After a demanding audit and testing process, Super Walter machines meet European regulations. The gateway to the market of the old continent.","og_title":"Super Walter conquers Europe: CE certification","og_description":"Our machines meet European regulations.","category_label":"Corporate","subcategory_label":"Certifications","hero_image_alt":"Tractor with a Super Walter implement on a hillside","lead":"Our machines meet European regulations. A huge step for exports and a validation of Argentine engineering.","body_paragraphs":["After a demanding audit and testing process, our machines meet European regulations. It is the gateway to the market of the old continent and, above all, confirmation that the engineering we do in Las Parejas is up to any standard in the world.","CE certification backs the safety and manufacturing quality standards of our seeders, an essential requirement to offer them in Europe. Behind that seal are years of work by the entire technical team at Búfalo S.A.","We keep betting on taking Argentine engineering ever further, without losing the closeness to the local producers who saw us grow."],"chips":["Certifications","Exports"],"cta_text":"Ask about exports","featured_desc":"After a demanding audit and testing process, our machines meet European regulations. It is the gateway to the market of the old continent and, above all, confirmation that the engineering we do in Las Parejas is up to any standard in the world.","featured_link_text":"Read the full story"}') ON DUPLICATE KEY UPDATE titulo = VALUES(titulo), orden = VALUES(orden), data = VALUES(data);
INSERT INTO contenido (coleccion, slug, titulo, orden, data) VALUES ('novedades_en', 'hospital-las-parejas', 'New intensive care units at the Las Parejas Hospital', 2, '{"slug":"hospital-las-parejas","title":"New intensive care units at the Las Parejas Hospital","seo_title":"New intensive care units at the Las Parejas Hospital · News","seo_description":"We joined the opening of the new facilities at our city hospital. A commitment to the well-being of the community where we began.","og_title":"New intensive care units at the Las Parejas Hospital","og_description":"A commitment to the well-being of the community where we began.","category_label":"Community","subcategory_label":"Social responsibility","hero_image_alt":"Harvested field at sunset","lead":"We joined the opening of the new facilities at our city hospital. A commitment to the well-being of the community where we began.","body_paragraphs":["We joined the opening of the new intensive care units at the Las Parejas Hospital, a project that improves medical care in our city and the surrounding area.","As a family company, our commitment goes beyond the factory: we want Las Parejas to keep growing, with better services for the people who live here.","We will keep doing our part for the community where we began, just as we work to make sure every seeder supports producers across the country."],"chips":[],"cta_text":"Get to know the company"}') ON DUPLICATE KEY UPDATE titulo = VALUES(titulo), orden = VALUES(orden), data = VALUES(data);
INSERT INTO contenido (coleccion, slug, titulo, orden, data) VALUES ('novedades_en', 'ferias-internacionales-2024', 'International trade shows 2024', 3, '{"slug":"ferias-internacionales-2024","title":"International trade shows 2024","seo_title":"International trade shows 2024 · Super Walter News","seo_description":"We bring Super Walter machines to the world\'s leading exhibitions. The whole year\'s trade show schedule, in one place.","og_title":"International trade shows 2024","og_description":"The whole year\'s trade show schedule, in one place.","category_label":"Trade shows","subcategory_label":"Schedule","hero_image_alt":"Super Walter seeder pulled by a tractor hard at work","lead":"We bring Super Walter machines to the world\'s leading exhibitions. The whole year\'s schedule, in one place.","body_paragraphs":["We bring Super Walter machines to the world\'s leading exhibitions. The whole year\'s schedule, in one place.","Expoagro, AgroActiva, La Rural and Aapresid were some of the year\'s stops, with the full lineup showing its work in the field.","If you are planning your visit to an upcoming show, write to us and we will arrange a meeting with our sales team."],"chips":["Trade shows","2024 schedule"],"cta_text":"Arrange a visit"}') ON DUPLICATE KEY UPDATE titulo = VALUES(titulo), orden = VALUES(orden), data = VALUES(data);
INSERT INTO contenido (coleccion, slug, titulo, orden, data) VALUES ('novedades_en', 'expoagro-2024', 'Expoagro 2024', 4, '{"slug":"expoagro-2024","title":"Expoagro 2024","seo_title":"Expoagro 2024 · Super Walter News","seo_description":"We were at the largest field show in the country, presenting the full lineup and talking with producers from every region.","og_title":"Expoagro 2024","og_description":"We were at the largest field show in the country.","category_label":"Trade shows","subcategory_label":"Expoagro","hero_image_alt":"Front view of a Super Walter seeder over a field","lead":"We were at the largest field show in the country, presenting the full lineup and talking with producers from every region.","body_paragraphs":["We were at the largest field show in the country, presenting the full lineup and talking with producers from every region.","The full lineup, led by the W1770 Triflex, was on display throughout the days of the show.","Thank you to all the producers who stopped by the booth to see the machines up close."],"chips":[],"cta_text":"See the full lineup"}') ON DUPLICATE KEY UPDATE titulo = VALUES(titulo), orden = VALUES(orden), data = VALUES(data);
INSERT INTO contenido (coleccion, slug, titulo, orden, data) VALUES ('novedades_en', 'agroactiva-2024', 'AgroActiva 2024', 5, '{"slug":"agroactiva-2024","title":"AgroActiva 2024","seo_title":"AgroActiva 2024 · Super Walter News","seo_description":"Another edition all about the field. Live demonstrations and the machines truly at work, which is the best way to understand them.","og_title":"AgroActiva 2024","og_description":"Another edition all about the field, with the machines truly at work.","category_label":"Trade shows","subcategory_label":"AgroActiva","hero_image_alt":"Tractor with a Super Walter seeder on a hillside at sunset","lead":"Another edition all about the field. Live demonstrations and the machines truly at work, which is the best way to understand them.","body_paragraphs":["Another edition all about the field. Live demonstrations and the machines truly at work, which is the best way to understand them.","The live demonstrations let visitors see Super Walter seeders working in the field, just as they do every day on farms across the country.","Another chance to talk face to face with producers and technicians from different farming regions."],"chips":[],"cta_text":"See the full lineup"}') ON DUPLICATE KEY UPDATE titulo = VALUES(titulo), orden = VALUES(orden), data = VALUES(data);
INSERT INTO contenido (coleccion, slug, titulo, orden, data) VALUES ('novedades_en', 'la-rural-2024', 'We returned to La Rural 2024', 6, '{"slug":"la-rural-2024","title":"We returned to La Rural 2024","seo_title":"We returned to La Rural 2024 · Super Walter News","seo_description":"Back in Palermo, with the brand present at the most traditional show in Argentine agriculture.","og_title":"We returned to La Rural 2024","og_description":"Back in Palermo, with the brand present at the most traditional show.","category_label":"Trade shows","subcategory_label":"La Rural","hero_image_alt":"Aerial view of the Super Walter W650 Imperial seeder","lead":"Back in Palermo, with the brand present at the most traditional show in Argentine agriculture.","body_paragraphs":["Back in Palermo, with the brand present at the most traditional show in Argentine agriculture.","Another edition of the Palermo show with Super Walter on hand, sharing the floor with the most traditional names in Argentine agriculture.","Thank you to everyone who came to see our machines in the capital."],"chips":[],"cta_text":"See the full lineup"}') ON DUPLICATE KEY UPDATE titulo = VALUES(titulo), orden = VALUES(orden), data = VALUES(data);
INSERT INTO contenido (coleccion, slug, titulo, orden, data) VALUES ('novedades_en', 'scaloni-nuevo-cliente', 'Lionel Scaloni, new Super Walter customer!', 7, '{"slug":"scaloni-nuevo-cliente","title":"Lionel Scaloni, new Super Walter customer!","seo_title":"Lionel Scaloni, new Super Walter customer! · News","seo_description":"The national team coach chose our machines for his farm. A huge source of pride for the whole Super Walter family.","og_title":"Lionel Scaloni, new Super Walter customer!","og_description":"The national team coach chose our machines for his farm.","category_label":"Corporate","subcategory_label":"Customers","hero_image_alt":"Golden wheat field under a clear sky","lead":"The national team coach chose our machines for his farm. A huge source of pride for the whole Super Walter family.","body_paragraphs":["The national team coach chose our machines for his farm. A huge source of pride for the whole Super Walter family.","That someone so well known across the country chose our seeders for his own farm is a huge source of pride for the entire Búfalo S.A. team.","We keep working so that every producer, famous or not, finds in Super Walter the right seeder for the way they sow."],"chips":["Corporate","Customers"],"cta_text":"Request advice"}') ON DUPLICATE KEY UPDATE titulo = VALUES(titulo), orden = VALUES(orden), data = VALUES(data);
INSERT INTO contenido (coleccion, slug, titulo, orden, data) VALUES ('novedades_en', 'aapresid-2024', 'Super Walter at Aapresid 2024: Scaloni, the new face of the company', 8, '{"slug":"aapresid-2024","title":"Super Walter at Aapresid 2024: Scaloni, the new face of the company","seo_title":"Super Walter at Aapresid 2024: Scaloni, the new face of the company · News","seo_description":"Innovation and commitment at the no-till seeding congress, where we introduced Lionel Scaloni as the new face of the brand.","og_title":"Super Walter at Aapresid 2024: Scaloni, the new face of the company","og_description":"We introduced Lionel Scaloni as the new face of the brand.","category_label":"Corporate","subcategory_label":"Aapresid","hero_image_alt":"W1770 seeder in the field","lead":"Innovation and commitment at the no-till seeding congress, where we introduced Lionel Scaloni as the new face of the brand.","body_paragraphs":["Innovation and commitment at the no-till seeding congress, where we introduced Lionel Scaloni as the new face of the brand.","The Aapresid congress brings together leaders in no-till seeding from across the country every year, and in 2024 it was the stage chosen to present Lionel Scaloni as the new face of Super Walter.","Innovation, commitment and closeness to the producer: the same values we put into every seeder that leaves our plant."],"chips":["Corporate","Aapresid"],"cta_text":"Request advice"}') ON DUPLICATE KEY UPDATE titulo = VALUES(titulo), orden = VALUES(orden), data = VALUES(data);
INSERT INTO contenido (coleccion, slug, titulo, orden, data) VALUES ('novedades_en', 'super-plan-financiacion', 'New SUPER PLAN for direct financing', 9, '{"slug":"super-plan-financiacion","title":"New SUPER PLAN for direct financing","seo_title":"New SUPER PLAN for direct financing · Super Walter News","seo_description":"Direct factory financing, with no middlemen, so you can renew your equipment on terms designed for producers.","og_title":"New SUPER PLAN for direct financing","og_description":"Direct factory financing, with no middlemen.","category_label":"Sales","subcategory_label":"Financing","hero_image_alt":"Super Walter seeder working in a vast golden field","lead":"Direct factory financing, with no middlemen, so you can renew your equipment on terms designed for producers.","body_paragraphs":["Direct factory financing, with no middlemen, so you can renew your equipment on terms designed for producers.","The SUPER PLAN lets you get a Super Walter seeder with direct factory financing, with no intermediaries involved.","Check with our sales team for current terms and find the payment option that best fits your season."],"chips":["Sales","Financing"],"cta_text":"Ask about the plan","listing_link_text":"Ask about the plan"}') ON DUPLICATE KEY UPDATE titulo = VALUES(titulo), orden = VALUES(orden), data = VALUES(data);
INSERT INTO contenido (coleccion, slug, titulo, orden, data) VALUES ('catalogo_en', 'sembradora-de-granos-finos-erca-modelo-gf-39-l-ineas-a-26-cm', 'ERCA GF Fine Grain Seeder, 39 Rows at 26 cm', 1, '{"slug":"sembradora-de-granos-finos-erca-modelo-gf-39-l-ineas-a-26-cm","title":"ERCA GF Fine Grain Seeder, 39 Rows at 26 cm","description_html":"<p><strong>ERCA GF Fine Grain Seeder</strong></p>\\r\\n\\r\\n<ul>\\r\\n \\t<li>39 rows with 26 cm spacing</li>\\r\\n \\t<li>Pneumatic with Matermacc metering units</li>\\r\\n \\t<li>Equipped with DDP</li>\\r\\n \\t<li>Gauge wheels</li>\\r\\n \\t<li>Toothed closing wheels</li>\\r\\n \\t<li>Seed press wheels and turbo blades</li>\\r\\n \\t<li>In-row fertilization</li>\\r\\n \\t<li>Hydraulic markers</li>\\r\\n</ul>\\r\\n<p><strong>YEAR 2018</strong></p>\\r\\n\\r\\n<strong>U$D 148,000</strong>","specs":[],"image_alt":"ERCA GF Fine Grain Seeder, 39 Rows at 26 cm"}') ON DUPLICATE KEY UPDATE titulo = VALUES(titulo), orden = VALUES(orden), data = VALUES(data);
INSERT INTO contenido (coleccion, slug, titulo, orden, data) VALUES ('catalogo_en', 'sembradora-de-granos-gruesos-giorgi-modelo-pr8000-12-surcos-a-52-50-cm', 'GIORGI PR8000 Coarse Grain Seeder, 12 Rows at 52.5 cm', 2, '{"slug":"sembradora-de-granos-gruesos-giorgi-modelo-pr8000-12-surcos-a-52-50-cm","title":"GIORGI PR8000 Coarse Grain Seeder, 12 Rows at 52.5 cm","description_html":"<p><strong>GIORGI PR8000 Coarse Grain Seeder</strong></p>\\r\\n\\r\\n<ul>\\r\\n \\t<li>12 rows with 52.5 cm spacing</li>\\r\\n \\t<li>Serial No.: 11797</li>\\r\\n</ul>\\r\\n<p><strong>YEAR 2004</strong></p>","specs":[],"image_alt":"GIORGI PR8000 Coarse Grain Seeder, 12 Rows at 52.5 cm"}') ON DUPLICATE KEY UPDATE titulo = VALUES(titulo), orden = VALUES(orden), data = VALUES(data);
INSERT INTO contenido (coleccion, slug, titulo, orden, data) VALUES ('catalogo_en', 'sembradora-de-granos-finos-super-walter-w326-de-26-a-17-55cm', 'SUPER WALTER W326 Fine Grain Seeder, from 26 to 17.55 cm spacing', 3, '{"slug":"sembradora-de-granos-finos-super-walter-w326-de-26-a-17-55cm","title":"SUPER WALTER W326 Fine Grain Seeder, from 26 to 17.55 cm spacing","description_html":"<p><strong>SUPER WALTER Fine Grain Seeder</strong></p>\\r\\n\\r\\n<ul>\\r\\n \\t<li>W326 model, 26 rows with 17.55 cm spacing</li>\\r\\n \\t<li>DDP</li>\\r\\n \\t<li>Equipped with accessories for no-till seeding</li>\\r\\n \\t<li>Unified sheet-metal hopper for seed and in-row fertilizer + sheet-metal hopper for between-row fertilization</li>\\r\\n \\t<li>Single-disc fertilizer units</li>\\r\\n \\t<li>Hydraulic markers and tires</li>\\r\\n</ul>\\r\\n<p><strong>YEAR 2000</strong></p>","specs":[],"image_alt":"SUPER WALTER W326 Fine Grain Seeder, from 26 to 17.55 cm spacing"}') ON DUPLICATE KEY UPDATE titulo = VALUES(titulo), orden = VALUES(orden), data = VALUES(data);
INSERT INTO contenido (coleccion, slug, titulo, orden, data) VALUES ('catalogo_en', 'sembradora-marca-super-walter-w1770-serie-iv-de-21-a-35cm', 'SUPER WALTER W1770 Series IV Seeder, from 21 to 35 cm spacing', 4, '{"slug":"sembradora-marca-super-walter-w1770-serie-iv-de-21-a-35cm","title":"SUPER WALTER W1770 Series IV Seeder, from 21 to 35 cm spacing","description_html":"<p><strong>SUPER WALTER Fine Grain Seeder</strong></p>\\r\\n\\r\\n<ul>\\r\\n \\t<li>W1770 Series IV model, 21 rows with 35 cm spacing</li>\\r\\n \\t<li>DDP</li>\\r\\n \\t<li>Equipped with accessories for no-till seeding</li>\\r\\n \\t<li>2 7/8\\" x 15 solid gauge wheels</li>\\r\\n \\t<li>Toothed closing wheels</li>\\r\\n \\t<li>Teflon seed press wheels and turbo blades</li>\\r\\n \\t<li>Unified sheet-metal hopper for seed and in-row fertilizer</li>\\r\\n \\t<li>Rear mechanical coarse grain kit, 21 x 35 cm</li>\\r\\n \\t<li>AG-3000 seeding monitor</li>\\r\\n \\t<li>Hydraulic markers and tires</li>\\r\\n</ul>\\r\\n<p><strong>YEAR 2012</strong></p>","specs":[],"image_alt":"SUPER WALTER W1770 Series IV Seeder, from 21 to 35 cm spacing"}') ON DUPLICATE KEY UPDATE titulo = VALUES(titulo), orden = VALUES(orden), data = VALUES(data);
INSERT INTO contenido (coleccion, slug, titulo, orden, data) VALUES ('catalogo_en', 'sembradora-abonadora-agrometal-tx-de-14-a-52-50cm', 'Agrometal TX Seeder-Fertilizer, 14 Rows at 52.5 cm', 5, '{"slug":"sembradora-abonadora-agrometal-tx-de-14-a-52-50cm","title":"Agrometal TX Seeder-Fertilizer, 14 Rows at 52.5 cm","description_html":"<p><strong>Agrometal Coarse Grain Seeder-Fertilizer</strong></p>\\r\\n\\r\\n<ul>\\r\\n \\t<li>TX model, 14 rows with 52.5 cm spacing</li>\\r\\n \\t<li>Mechanical</li>\\r\\n \\t<li>Side fertilization with fertilizer blades</li>\\r\\n \\t<li>Hydraulic markers and tires</li>\\r\\n</ul>\\r\\n<p><strong>YEAR 2008</strong></p>","specs":[],"image_alt":"Agrometal TX Seeder-Fertilizer, 14 Rows at 52.5 cm"}') ON DUPLICATE KEY UPDATE titulo = VALUES(titulo), orden = VALUES(orden), data = VALUES(data);
INSERT INTO contenido (coleccion, slug, titulo, orden, data) VALUES ('catalogo_en', 'sembradora-super-walter-w630-20-x-52-5', 'SUPER WALTER W630 Seeder, 20 x 52.5 cm', 6, '{"slug":"sembradora-super-walter-w630-20-x-52-5","title":"SUPER WALTER W630 Seeder, 20 x 52.5 cm","description_html":"<p><strong>SUPER WALTER - W630 Model, 20 Rows with 52.50 cm Spacing</strong><br>\\r\\n<ul><br>\\r\\n \\t<li>2 tandem seeding modules</li><br>\\r\\n \\t<li>PNEUMATIC</li><br>\\r\\n \\t<li>GERONZI seed meters</li><br>\\r\\n \\t<li>Equipped with accessories for no-till seeding</li><br>\\r\\n \\t<li>4 1/2\\" X 15\\" gauge wheels</li><br>\\r\\n \\t<li>Seed press wheels</li><br>\\r\\n \\t<li>Turbo blades and serrated closing wheels</li><br>\\r\\n \\t<li>Dual-purpose fertilizer hopper (half for seed / half for in-row fertilizer)</li><br>\\r\\n \\t<li>Hydraulic markers and tires</li><br>\\r\\n \\t<li>YEAR: 2004</li><br>\\r\\n \\t<li>Nos.: 998-999</li><br>\\r\\n</ul></p>","specs":[],"image_alt":"SUPER WALTER W630 Seeder, 20 x 52.5 cm"}') ON DUPLICATE KEY UPDATE titulo = VALUES(titulo), orden = VALUES(orden), data = VALUES(data);
INSERT INTO contenido (coleccion, slug, titulo, orden, data) VALUES ('catalogo_en', 'sembradora-marca-super-walter-w650-autotrailer-18-a-42-cm', 'SUPER WALTER W650 AUTOTRAILER Seeder, 18 rows at 42 cm spacing', 7, '{"slug":"sembradora-marca-super-walter-w650-autotrailer-18-a-42-cm","title":"SUPER WALTER W650 AUTOTRAILER Seeder, 18 rows at 42 cm spacing","description_html":"<ul>\\r\\n \\t<li><strong>SUPER WALTER Coarse Grain Seeder</strong>\\r\\n<ul>\\r\\n \\t<li>W650 AUTOTRAILER model, 18 rows with 42 cm spacing</li>\\r\\n \\t<li>Equipped with accessories for no-till seeding</li>\\r\\n \\t<li>Geronzi pneumatic metering units</li>\\r\\n \\t<li>Double rear hopper + double front hopper</li>\\r\\n \\t<li>Double fertilization</li>\\r\\n \\t<li>Wheat seeding kit</li>\\r\\n \\t<li>Hydraulic markers and tires</li>\\r\\n</ul>\\r\\n<strong>YEAR 2013</strong></li>\\r\\n</ul>","specs":[],"image_alt":"SUPER WALTER W650 AUTOTRAILER Seeder, 18 rows at 42 cm spacing"}') ON DUPLICATE KEY UPDATE titulo = VALUES(titulo), orden = VALUES(orden), data = VALUES(data);
INSERT INTO contenido (coleccion, slug, titulo, orden, data) VALUES ('catalogo_en', 'sembradora-super-walter-w1770-serie-iv-de-51-a-21', 'SUPER WALTER W1770 SERIES IV Seeder, 51 rows at 21 cm spacing', 8, '{"slug":"sembradora-super-walter-w1770-serie-iv-de-51-a-21","title":"SUPER WALTER W1770 SERIES IV Seeder, 51 rows at 21 cm spacing","description_html":"<ul>\\r\\n \\t<li><strong>SUPER WALTER Fine Grain Seeder</strong>\\r\\n<ul>\\r\\n \\t<li>W1770 SERIES IV model, 51 rows with 21 cm spacing</li>\\r\\n \\t<li>Equipped with accessories for no-till seeding</li>\\r\\n \\t<li>Unified sheet-metal hopper (for seed and in-row fertilizer)</li>\\r\\n \\t<li>Rear coarse grain kit, 26 rows at 42 cm spacing</li>\\r\\n \\t<li>Mechanical, with polymer bottoms and square gearbox</li>\\r\\n \\t<li>Hydraulic markers and tires</li>\\r\\n</ul>\\r\\n<strong>YEAR 2007</strong></li>\\r\\n</ul>","specs":[],"image_alt":"SUPER WALTER W1770 SERIES IV Seeder, 51 rows at 21 cm spacing"}') ON DUPLICATE KEY UPDATE titulo = VALUES(titulo), orden = VALUES(orden), data = VALUES(data);
INSERT INTO contenido (coleccion, slug, titulo, orden, data) VALUES ('catalogo_en', 'sembradora-super-walter-w1770-serie-iv-de-33-a-19-1', 'SUPER WALTER W1770 SERIES IV Seeder, 33 rows at 19.1 cm spacing', 9, '{"slug":"sembradora-super-walter-w1770-serie-iv-de-33-a-19-1","title":"SUPER WALTER W1770 SERIES IV Seeder, 33 rows at 19.1 cm spacing","description_html":"<ul>\\r\\n \\t<li><strong>SUPER WALTER Fine Grain Seeder</strong>\\r\\n<ul>\\r\\n \\t<li>W1770 SERIES IV model, 33 rows with 19.1 cm spacing</li>\\r\\n \\t<li>Equipped with accessories for no-till seeding</li>\\r\\n \\t<li>Unified sheet-metal hopper (for seed and in-row fertilizer)</li>\\r\\n \\t<li>Alfalfa seed box</li>\\r\\n \\t<li>Rear coarse grain kit, 17 rows at 38 cm spacing</li>\\r\\n \\t<li>Mechanical, with polymer bottoms and square gearbox</li>\\r\\n \\t<li>Hydraulic markers and tires</li>\\r\\n</ul>\\r\\n<strong>YEAR 2017</strong></li>\\r\\n</ul>","specs":[],"image_alt":"SUPER WALTER W1770 SERIES IV Seeder, 33 rows at 19.1 cm spacing"}') ON DUPLICATE KEY UPDATE titulo = VALUES(titulo), orden = VALUES(orden), data = VALUES(data);
INSERT INTO contenido (coleccion, slug, titulo, orden, data) VALUES ('catalogo_en', 'w660', 'W660', 10, '{"slug":"w660","title":"W660","description_html":"<h3>Advanced Technology and Operator Convenience:</h3>\\r\\n<p>Our new seeder features a hydraulic lifting drawbar, designed to provide simpler and more efficient operation, <strong>eliminating the need for manual intervention by the operator.</strong> In addition, its lower hydraulic consumption ensures optimal performance at all times.</p>\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n<h3>Versatility in Size:</h3>\\r\\n<p>The available size range, from 20 rows at 52.5 cm to 32 rows at 52.5 cm, with options for additional configurations, allows farmers to adapt the machine to their specific needs.</p>\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n<h3>Modular Design with Connecting Hinges:</h3>\\r\\n<p>This design allows a single rotational movement between odd-numbered modules, streamlining operations and facilitating adaptation to different conditions.</p>\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n<h3>Hinges with Sliding Pin System:</h3>\\r\\n<p>This system provides greater control over the rotation of the seeding units. Rotation limits ensure precise seeding in rows spaced 35 to 38 cm apart, which is essential for coarse grain production.</p>","specs":[],"image_alt":"W660"}') ON DUPLICATE KEY UPDATE titulo = VALUES(titulo), orden = VALUES(orden), data = VALUES(data);
INSERT INTO contenido (coleccion, slug, titulo, orden, data) VALUES ('catalogo_en', 'w650-imperial', 'W650 IMPERIAL', 11, '{"slug":"w650-imperial","title":"W650 IMPERIAL","description_html":"<h3>Forward Transport Folding:</h3>\\r\\n<p>3.10 m tire footprint | 4 m total width when folded, with ample ground clearance.</p>","specs":["6-wheel transport tires 400/55 x 22.5","Hydraulic Variable Seeding and Fertilization Rate Control","Independent hydraulic power unit (optional)","Optional cutting by furrow or section","Pneumatic or Mechanical Seeding System","Seeding Monitor and Variable Rate Control Series","Simple fertilization in the row or off the row"],"image_alt":"W650 IMPERIAL"}') ON DUPLICATE KEY UPDATE titulo = VALUES(titulo), orden = VALUES(orden), data = VALUES(data);
INSERT INTO contenido (coleccion, slug, titulo, orden, data) VALUES ('catalogo_en', 'w650-autotrailer', 'W650 AUTOTRAILER', 12, '{"slug":"w650-autotrailer","title":"W650 AUTOTRAILER","description_html":"<h3>Frame:</h3>\\r\\n<p>It features a solid and robust frame designed to withstand the most demanding conditions, both during operation and transport. The row-unit mounting system is faster and easier to adjust to all row spacings from 350 mm onwards. The components are designed to achieve precision seeding and a long service life while maintaining optimal operating conditions.</p>\\r\\n<p>Hoppers:\\r\\nHigh-capacity plastic hoppers with dual compartments for in-row and between-row fertilization. Foldable divider to combine the capacity or split it into two compartments. Chevron-type metering units with emptying cover for easy cleaning. Between-row fertilizer application through an angled cutting blade with a gauge wheel for precise placement at the desired location and depth.</p>","specs":[],"image_alt":"W650 AUTOTRAILER"}') ON DUPLICATE KEY UPDATE titulo = VALUES(titulo), orden = VALUES(orden), data = VALUES(data);
INSERT INTO contenido (coleccion, slug, titulo, orden, data) VALUES ('catalogo_en', 'w650', 'W650', 13, '{"slug":"w650","title":"W650","description_html":"<p>This model features larger-capacity hoppers, allowing fertilization both in-row and alongside the seed row.</p>","specs":["Dual-Purpose Seed Hopper","Fertilizer Hopper","Fertilizes in rows with direct drop to the row unit","Movable Blade System","Single and double fertilization"],"image_alt":"W650"}') ON DUPLICATE KEY UPDATE titulo = VALUES(titulo), orden = VALUES(orden), data = VALUES(data);
INSERT INTO contenido (coleccion, slug, titulo, orden, data) VALUES ('catalogo_en', 'w630-3-puntos', 'W630 3-Point Hitch', 14, '{"slug":"w630-3-puntos","title":"W630 3-Point Hitch","description_html":"<h3>Fertilization:</h3>\\r\\n<p>High-capacity plastic hoppers with 126 liters per row. The metering units are chevron-type and feature an emptying cover for easy cleaning. It can fertilize both in-row and between-row simultaneously, using two 36-speed gearboxes for accurate metering.</p>\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n<h3>Seeding Metering Unit:</h3>\\r\\n<p>Seeding density is achieved through 32-speed oil-bath gearboxes protected by a safety release mechanism. They allow the exact quantity of seed to be sown to be metered by simply positioning the lever according to the seeding chart.</p>\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n<h3>Hydraulic System:</h3>\\r\\n<p>The Super Walter W630 seeder is equipped with a hydraulic circuit operated by a single tractor control to activate the two marker cylinders, with their corresponding sequential valve.</p>\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n<h3>Seeding and Fertilization System:</h3>\\r\\n<p>For in-row fertilizer placement, the first toolbar features a cutting blade for no-till seeding. It is equipped with 16\\" corrugated blades (turbo optional), with either shear-bolt or spring release, which open the furrow. Fertilizer is delivered independently of the seed, placing it precisely in front of and below the seed.</p>","specs":[],"image_alt":"W630 3-Point Hitch"}') ON DUPLICATE KEY UPDATE titulo = VALUES(titulo), orden = VALUES(orden), data = VALUES(data);
INSERT INTO contenido (coleccion, slug, titulo, orden, data) VALUES ('catalogo_en', 'w630', 'W630', 15, '{"slug":"w630","title":"W630","description_html":"<h3>Single and Double Fertilization:</h3>\\r\\n<p>Precise metering is achieved through mechanical variable-rate gearboxes or a hydraulic motor. Seed distribution is carried out through a mechanical or pneumatic metering system with 54-speed gearboxes.</p>\\r\\n\\r\\n<h3>Mechanical Metering:</h3>\\r\\n<p>Our system provides gentle and smooth seed handling, reducing the possibility of seed damage. Maintenance-free. No greasing required.</p>","specs":["Conventional and No-Till Seeding","Longitudinal Transport","Single and double fertilization","Variable row spacing"],"image_alt":"W630"}') ON DUPLICATE KEY UPDATE titulo = VALUES(titulo), orden = VALUES(orden), data = VALUES(data);
INSERT INTO contenido (coleccion, slug, titulo, orden, data) VALUES ('catalogo_en', 'w4500', 'W4500', 16, '{"slug":"w4500","title":"W4500","description_html":"<h3>Longitudinal Transport:</h3>\\r\\n<p>This model offers the option of incorporating a front hitch transport kit, allowing the operator to couple and uncouple the seeder for different applications.</p>\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n<h3>Excellent Ground Following:</h3>\\r\\n<p>Its ability to follow the terrain with more than 30 cm of ground contouring makes a difference when seeding rice and fine grains. In addition, this machine is equipped with special row units specifically designed for these crops.</p>","specs":["All sizes from 17 x 17.5 to 62 x 17.5","High-Capacity Hoppers","Integrated Module Systems – Tandem","Longitudinal Transport System (optional)","Special row units for rice and fine grain seeding","Variable row spacings: 17.5 – 21 – 26.25 cm"],"image_alt":"W4500"}') ON DUPLICATE KEY UPDATE titulo = VALUES(titulo), orden = VALUES(orden), data = VALUES(data);
INSERT INTO contenido (coleccion, slug, titulo, orden, data) VALUES ('catalogo_en', 'w1770-triflex', 'W1770 TRIFLEX', 17, '{"slug":"w1770-triflex","title":"W1770 TRIFLEX","description_html":"<h3>Hydraulic Innovation:</h3>\\r\\n<p>Effortless Operation: The W1770 TRIFLEX is equipped with a hydraulic lifting drawbar, designed to make the operator\'s work easier. This feature eliminates the need for manual intervention, making each seeding day faster and more efficient, while its low hydraulic consumption ensures optimal performance on any terrain.</p>\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n<p>More Capacity, More Performance\\r\\nWith an improved chassis that supports a greater number of hoppers, the W1770 TRIFLEX increases its seeding capacity, allowing you to cover more hectares in less time. It is the perfect tool for maximizing seeding time across large agricultural areas.</p>\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\nVersatility and Precision on All Types of Soil\\r\\nThe W1770 TRIFLEX\'s advanced technology ensures superior ground following, guaranteeing uniform depth in every furrow and precise seed distribution.\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\nUnmatched Productivity in Fine Grains\\r\\nThe W1770 TRIFLEX seeder not only optimizes the seeding process, but also provides unmatched versatility, adapting to different soil types and conditions. With this seeder, every pass is synonymous with efficiency, precision, and performance.","specs":[],"image_alt":"W1770 TRIFLEX"}') ON DUPLICATE KEY UPDATE titulo = VALUES(titulo), orden = VALUES(orden), data = VALUES(data);
INSERT INTO contenido (coleccion, slug, titulo, orden, data) VALUES ('catalogo_en', 'w1770-serie-iv', 'W1770 SERIES IV', 18, '{"slug":"w1770-serie-iv","title":"W1770 SERIES IV","description_html":"<h3>Frame:</h3>\\r\\n<p>Solid and robust. Designed to withstand the most demanding conditions, both during operation and transport.</p>\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n<h3>Alfalfa Hopper:</h3>\\r\\n<p>Direct drop into the seeding unit. Forced-feed system. 36-speed gearbox.</p>\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n<h3>Fertilizer Hopper:</h3>\\r\\n<p>In-row fertilization with direct drop into the seeding unit. Chevron-type metering units with individual emptying and cleaning covers. Prevents fertilizer from being spread over the machine, avoiding the resulting inconveniences and damage.</p>\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n<h3>Dual-Purpose Seed Hopper:</h3>\\r\\n<p>Double fluted-feed rollers or chevron-type feeders.</p>","specs":[],"image_alt":"W1770 SERIES IV"}') ON DUPLICATE KEY UPDATE titulo = VALUES(titulo), orden = VALUES(orden), data = VALUES(data);
INSERT INTO contenido (coleccion, slug, titulo, orden, data) VALUES ('catalogo_en', 'w1770-air-drill-serie-v', 'W1770 AIR DRILL Series V', 19, '{"slug":"w1770-air-drill-serie-v","title":"W1770 AIR DRILL Series V","description_html":"<h3>Supply Cart:</h3>\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n<p>Consists of two individual hoppers, with a total capacity of 12,000 liters. 40/60% seed + fertilizer option. If necessary, an additional 1,200-liter hopper can be added, allocating capacity from the main hopper for increased fertilizer application.</p>\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n<h3>Ladders:</h3>\\r\\n<p>Internal and external ladders provide easy and safe access.</p>\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n<h3>Fertilization:</h3>\\r\\n<p>The XL – optional XXL – offers 3 possibilities:\\r\\n• In-row fertilization\\r\\n• Side-band fertilization\\r\\n• Double fertilization</p>\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n<h3>Hopper Cart Tires:</h3>\\r\\n<p>2 high-flotation 23.1 x 26 tires. Fenders and safety lighting for operation and transport.</p>","specs":[],"image_alt":"W1770 AIR DRILL Series V"}') ON DUPLICATE KEY UPDATE titulo = VALUES(titulo), orden = VALUES(orden), data = VALUES(data);
INSERT INTO contenido (coleccion, slug, titulo, orden, data) VALUES ('catalogo_en', 'sembradora-tedeschi-autotrailer-de-20-a-42cms', 'Tedeschi Autotrailer Seeder 20 rows at 42 cm spacing', 20, '{"slug":"sembradora-tedeschi-autotrailer-de-20-a-42cms","title":"Tedeschi Autotrailer Seeder 20 rows at 42 cm spacing","description_html":"<ul>\\r\\n \\t<li>Tedeschi Autotrailer coarse grain seeder</li>\\r\\n \\t<li>Mechanical</li>\\r\\n \\t<li>Seed only</li>\\r\\n \\t<li><strong>Year 2006</strong></li>\\r\\n</ul>","specs":[],"image_alt":"Tedeschi Autotrailer Seeder 20 rows at 42 cm spacing"}') ON DUPLICATE KEY UPDATE titulo = VALUES(titulo), orden = VALUES(orden), data = VALUES(data);
INSERT INTO contenido (coleccion, slug, titulo, orden, data) VALUES ('catalogo_en', 'sembradora-super-walter-w630-de-20-surcos-a-52-50cm', 'Super Walter W630 Seeder 20 rows at 52.5 cm spacing', 21, '{"slug":"sembradora-super-walter-w630-de-20-surcos-a-52-50cm","title":"Super Walter W630 Seeder 20 rows at 52.5 cm spacing","description_html":"<ul>\\r\\n \\t<li><strong>SUPER WALTER Fine Grain Seeder</strong>\\r\\n<ul>\\r\\n \\t<li>W630 model, 20 rows at 52.5 cm spacing (02 tandem modules)</li>\\r\\n \\t<li>Equipped with accessories for no-till seeding</li>\\r\\n \\t<li>Double fertilization</li>\\r\\n \\t<li>Fertilizer row units</li>\\r\\n \\t<li>With TIM wiring and sensors (monitor not included)</li>\\r\\n \\t<li>Hydraulic markers and tires</li>\\r\\n</ul>\\r\\n<strong>YEAR: 2010</strong></li>\\r\\n</ul>\\r\\n<strong>U$D 85,000</strong>","specs":[],"image_alt":"Super Walter W630 Seeder 20 rows at 52.5 cm spacing"}') ON DUPLICATE KEY UPDATE titulo = VALUES(titulo), orden = VALUES(orden), data = VALUES(data);
INSERT INTO contenido (coleccion, slug, titulo, orden, data) VALUES ('catalogo_en', 'sembradora-super-walter-w1770-serie-iv-de-29-a-21cms', 'Super Walter W1770 Series IV Seeder 29 rows at 21 cm spacing', 22, '{"slug":"sembradora-super-walter-w1770-serie-iv-de-29-a-21cms","title":"Super Walter W1770 Series IV Seeder 29 rows at 21 cm spacing","description_html":"<ul>\\r\\n \\t<li>Fine grain seeder, \\"Super Walter\\" brand</li>\\r\\n \\t<li>W1770 Series IV model</li>\\r\\n \\t<li>29 rows at 21 cm spacing</li>\\r\\n \\t<li>Equipped with accessories for no-till seeding</li>\\r\\n \\t<li>Unified sheet-metal hopper for seed and in-row fertilizer</li>\\r\\n \\t<li>Alfalfa seed box</li>\\r\\n \\t<li>Coarse grain kit, 11 x 52.50</li>\\r\\n \\t<li>Seeding monitor</li>\\r\\n \\t<li>Hydraulic markers</li>\\r\\n \\t<li>Tires</li>\\r\\n \\t<li><strong>Year 2008</strong></li>\\r\\n</ul>\\r\\n<strong>U$D 65,213</strong>","specs":[],"image_alt":"Super Walter W1770 Series IV Seeder 29 rows at 21 cm spacing"}') ON DUPLICATE KEY UPDATE titulo = VALUES(titulo), orden = VALUES(orden), data = VALUES(data);
INSERT INTO contenido (coleccion, slug, titulo, orden, data) VALUES ('catalogo_en', 'sembradora-pla-agp-2812-autotrailer-de-12-a-52-50cm', 'PLA AGP 2812 Autotrailer Seeder 12 rows at 52.5 cm spacing', 23, '{"slug":"sembradora-pla-agp-2812-autotrailer-de-12-a-52-50cm","title":"PLA AGP 2812 Autotrailer Seeder 12 rows at 52.5 cm spacing","description_html":"<ul>\\r\\n \\t<li><strong>PLA direct-seed coarse grain seeder</strong>\\r\\n<ul>\\r\\n \\t<li>AGP 2812 AUTOTRAILER model, 12 rows at 52.5 cm spacing, MECHANICAL</li>\\r\\n \\t<li>Side-band fertilization</li>\\r\\n \\t<li>Hydraulic markers and tires</li>\\r\\n</ul>\\r\\n<strong>YEAR 2008</strong></li>\\r\\n</ul>\\r\\n<strong>U$D 35,000</strong>","specs":[],"image_alt":"PLA AGP 2812 Autotrailer Seeder 12 rows at 52.5 cm spacing"}') ON DUPLICATE KEY UPDATE titulo = VALUES(titulo), orden = VALUES(orden), data = VALUES(data);
INSERT INTO contenido (coleccion, slug, titulo, orden, data) VALUES ('catalogo_en', 'sembradora-brioschi-autotrailer-de-41-x-19-38', 'Brioschi Autotrailer Seeder 41 rows at 19 / 38 cm spacing', 24, '{"slug":"sembradora-brioschi-autotrailer-de-41-x-19-38","title":"Brioschi Autotrailer Seeder 41 rows at 19 / 38 cm spacing","description_html":"<ul>\\r\\n \\t<li>\\"Brioschi\\" Autotrailer seeder</li>\\r\\n \\t<li>Mechanical</li>\\r\\n \\t<li>41 rows at 19/38 cm spacing</li>\\r\\n \\t<li>Coarse grain kit</li>\\r\\n \\t<li>Seeding monitor</li>\\r\\n \\t<li><strong>Year 2019</strong></li>\\r\\n</ul>","specs":[],"image_alt":"Brioschi Autotrailer Seeder 41 rows at 19 / 38 cm spacing"}') ON DUPLICATE KEY UPDATE titulo = VALUES(titulo), orden = VALUES(orden), data = VALUES(data);
INSERT INTO contenido (coleccion, slug, titulo, orden, data) VALUES ('catalogo_en', 'sembradora-agrometal-tx-mega-20-sucros-a-42cm', 'Agrometal TX Mega Seeder, 20 rows at 42 cm and 16 rows at 52.5 cm spacing', 25, '{"slug":"sembradora-agrometal-tx-mega-20-sucros-a-42cm","title":"Agrometal TX Mega Seeder, 20 rows at 42 cm and 16 rows at 52.5 cm spacing","description_html":"<ul>\\r\\n \\t<li>\\"Agrometal\\" coarse grain seeder</li>\\r\\n \\t<li>TX MEGA model</li>\\r\\n \\t<li>20 rows at 42 cm spacing</li>\\r\\n \\t<li>Variable, 16 rows at 52.5 cm spacing</li>\\r\\n \\t<li>PNEUMATIC with CLICK system</li>\\r\\n \\t<li>TIM variable hydraulic transmission</li>\\r\\n \\t<li>In-row fertilizer application</li>\\r\\n \\t<li>Seeding monitor and tires</li>\\r\\n</ul>\\r\\n&nbsp;","specs":[],"image_alt":"Agrometal TX Mega Seeder, 20 rows at 42 cm and 16 rows at 52.5 cm spacing"}') ON DUPLICATE KEY UPDATE titulo = VALUES(titulo), orden = VALUES(orden), data = VALUES(data);
