INSERT INTO contenido (coleccion, slug, titulo, orden, data) VALUES ('catalogo_en', 'sembradora-achilli-di-batista-63-x-17-5cm', 'Achilli Di Batista Seeder, 63 rows at 17.5 cm spacing', 27, '{"slug":"sembradora-achilli-di-batista-63-x-17-5cm","title":"Achilli Di Batista Seeder, 63 rows at 17.5 cm spacing","description_html":"<p>Fine grain seeder<br>\\r\\n<br>\\r\\n63 rows at 17.5 cm spacing (tandem)<br>\\r\\n<br>\\r\\nMATERMACC pneumatic coarse grain system at 70 cm<br>\\r\\n<br>\\r\\nTires in very good condition.<br>\\r\\n<br>\\r\\n<strong>Year 2010</strong></p>","specs":[],"image_alt":"Achilli Di Batista Seeder, 63 rows at 17.5 cm spacing"}') ON DUPLICATE KEY UPDATE titulo = VALUES(titulo), orden = VALUES(orden), data = VALUES(data);
INSERT INTO contenido (coleccion, slug, titulo, orden, data) VALUES ('catalogo_en', 'rastra-at', 'AT HARROW', 28, '{"slug":"rastra-at","title":"AT HARROW","description_html":"<h3>Versatile Working Widths:</h3>\\r\\n<p>With options of 5, 5.5, and 6 meters, you can adapt the Conditioner to your specific needs, ensuring efficient and uniform coverage of your field.</p>\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n<h3>Efficient Transport:</h3>\\r\\n<p>With a total transport width of 3.8 meters and a transport height of 3.5 meters, it is easy to move and transport, providing unmatched flexibility.</p>\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n<h3>Robust Design:</h3>\\r\\n<p>Built to withstand the harsh conditions of Argentine agriculture, our Conditioner is synonymous with quality and durability.</p>\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n\\r\\n<h3>Sustainability:</h3>\\r\\n<p>Contributes to more sustainable agricultural practices by reducing the need for chemical inputs and minimizing resource waste.</p>","specs":[],"image_alt":"AT HARROW"}') ON DUPLICATE KEY UPDATE titulo = VALUES(titulo), orden = VALUES(orden), data = VALUES(data);
INSERT INTO contenido (coleccion, slug, titulo, orden, data) VALUES ('catalogo_en', 'castor-c50', 'CASTOR C50', 29, '{"slug":"castor-c50","title":"CASTOR C50","description_html":"<h3>Maximum Stability:</h3>\\r\\n<p>Large, adjustable supports provide better weight distribution on the most challenging terrain. Great Versatility: continuous 360° rotation and an extendable arm ensure maximum utilization of its working capacity. Optimal Ground Adaptation: a wide range of support adjustments, combined with hydrostatic drive, provides the operator with safety and control.</p>","specs":["Afforestation","Construction","Drainage Channels","Dredging","Easy Transportation","Flooding","Road Works","Work on slopes"],"image_alt":"CASTOR C50"}') ON DUPLICATE KEY UPDATE titulo = VALUES(titulo), orden = VALUES(orden), data = VALUES(data);
INSERT INTO contenido (coleccion, slug, titulo, orden, data) VALUES ('catalogo_en', 'sembradora-super-walter-w1770-serie-iv-de-32-a-35cm', 'Super Walter W1770 Series IV Planter, 32 to 35 cm spacing', 30, '{"slug":"sembradora-super-walter-w1770-serie-iv-de-32-a-35cm","title":"Super Walter W1770 Series IV Planter, 32 to 35 cm spacing","description_html":"<p><strong>SUPER WALTER W1770 SERIES IV Fine Grain Planter</strong><br>\\r\\n<ul><br>\\r\\n \\t<li>32 rows with 35 cm spacing (02 tandem seeding modules)</li><br>\\r\\n \\t<li>Mechanical, with polymer seed meters</li><br>\\r\\n \\t<li>Equipped with accessories for no-till seeding</li><br>\\r\\n \\t<li>2 7/8\\" x 15\\" solid gauge wheels</li><br>\\r\\n \\t<li>Serrated closing wheels</li><br>\\r\\n \\t<li>Teflon seed press wheels and turbo blades</li><br>\\r\\n \\t<li>Unified sheet-metal hopper for seed and in-row fertilizer</li><br>\\r\\n \\t<li>Sheet-metal hopper for between-row fertilizer (without fertilizer units)</li><br>\\r\\n \\t<li>Mechanical rear large-grain kit: 32 x 35 cm and front: 11 x 52.50 cm</li><br>\\r\\n \\t<li>Hydraulic markers</li><br>\\r\\n \\t<li>AG-3000 seed monitor and tires</li><br>\\r\\n \\t<li>Serial No.: 0683-0684</li><br>\\r\\n</ul><br>\\r\\n<strong>YEAR 2013</strong></p>","specs":[],"image_alt":"Super Walter W1770 Series IV Planter, 32 to 35 cm spacing"}') ON DUPLICATE KEY UPDATE titulo = VALUES(titulo), orden = VALUES(orden), data = VALUES(data);
INSERT INTO contenido (coleccion, slug, titulo, orden, data) VALUES ('catalogo_en', 'sembradora-super-walter-w1770-serie-iv-de-41-a-17-5cm', 'Super Walter W1770 Series IV Planter, 41 Rows at 17.5 cm spacing', 31, '{"slug":"sembradora-super-walter-w1770-serie-iv-de-41-a-17-5cm","title":"Super Walter W1770 Series IV Planter, 41 Rows at 17.5 cm spacing","description_html":"<p><strong>SUPER WALTER Series IV Fine Grain Planter</strong><br>\\r\\n<ul><br>\\r\\n \\t<li>41 rows with 17.5 cm spacing</li><br>\\r\\n \\t<li>DDP</li><br>\\r\\n \\t<li>Equipped with accessories for no-till seeding</li><br>\\r\\n \\t<li>2 7/8\\" x 15\\" solid gauge wheels</li><br>\\r\\n \\t<li>Serrated closing wheels</li><br>\\r\\n \\t<li>Teflon seed press wheels and turbo blades</li><br>\\r\\n \\t<li>Unified sheet-metal hopper for seed and in-row fertilizer</li><br>\\r\\n \\t<li>Alfalfa seed box</li><br>\\r\\n \\t<li>Mechanical rear large-grain kit: 11 x 70 cm</li><br>\\r\\n \\t<li>Hydraulic markers and tires</li><br>\\r\\n \\t<li>Serial No.: 0734</li><br>\\r\\n</ul><br>\\r\\n<strong>YEAR 2016</strong></p>","specs":[],"image_alt":"Super Walter W1770 Series IV Planter, 41 Rows at 17.5 cm spacing"}') ON DUPLICATE KEY UPDATE titulo = VALUES(titulo), orden = VALUES(orden), data = VALUES(data);
INSERT INTO contenido (coleccion, slug, titulo, orden, data) VALUES ('catalogo_en', 'sembradora-brioschi-autotrailer-16-a-52-5-cm', 'Brioschi Autotrailer Planter, 16 to 52.5 cm spacing', 32, '{"slug":"sembradora-brioschi-autotrailer-16-a-52-5-cm","title":"Brioschi Autotrailer Planter, 16 to 52.5 cm spacing","description_html":"<p><strong>Heavy Grain Planter for No-Till Seeding - \\"BRIOSCHI\\" Brand -</strong><br>\\r\\n<ul><br>\\r\\n \\t<li>AUTOTRAILER Model, 16 rows at 52.50 cm spacing</li><br>\\r\\n \\t<li>PNEUMATIC with Geronzi seed meters</li><br>\\r\\n \\t<li>Double fertilization</li><br>\\r\\n \\t<li>Control AGRO 5100 seed monitor</li><br>\\r\\n \\t<li>Tainar system</li><br>\\r\\n \\t<li>Blades with pneumatic piston</li><br>\\r\\n \\t<li>Hydraulic markers and tires</li><br>\\r\\n \\t<li>YEAR: 2002</li><br>\\r\\n</ul></p>","specs":[],"image_alt":"Brioschi Autotrailer Planter, 16 to 52.5 cm spacing"}') ON DUPLICATE KEY UPDATE titulo = VALUES(titulo), orden = VALUES(orden), data = VALUES(data);
INSERT INTO contenido (coleccion, slug, titulo, orden, data) VALUES ('catalogo_en', 'sembradora-super-walter-w650-imperial-33-a-35-cm', 'Super Walter W650 Imperial Planter, 33 to 35 cm spacing', 33, '{"slug":"sembradora-super-walter-w650-imperial-33-a-35-cm","title":"Super Walter W650 Imperial Planter, 33 to 35 cm spacing","description_html":"<p><strong>SUPER WALTER W650 IMPERIAL Heavy Grain Planter</strong><br>\\r\\n<ul><br>\\r\\n \\t<li>33 rows with 35 cm spacing</li><br>\\r\\n \\t<li>PNEUMATIC</li><br>\\r\\n \\t<li>Equipped with Matermacc seed meters</li><br>\\r\\n \\t<li>Flexible drives</li><br>\\r\\n \\t<li>Dual-purpose hopper (half for seed - half for in-row fertilizer)</li><br>\\r\\n \\t<li>FGS seed monitor</li><br>\\r\\n</ul><br>\\r\\n<strong>YEAR: 2023</strong></p>","specs":[],"image_alt":"Super Walter W650 Imperial Planter, 33 to 35 cm spacing"}') ON DUPLICATE KEY UPDATE titulo = VALUES(titulo), orden = VALUES(orden), data = VALUES(data);
